import {storeLinks} from './store-links.js?v=20261004-avoid';
import {flags} from './filter-art.js?v=20261004-avoid';
import {getGuideChoices} from './guide.js?v=20261004-avoid';
import {languages,messages} from './i18n.js?v=20261004-avoid';
import {dishes,categories,ingredientKeys,storeInfo,recommendations,recommendedMenuIds,filterDishes} from './data.js?v=20261004-avoid';
import {icons} from './icons.js?v=20261002-final';
const app=document.querySelector('#app'),dialog=document.querySelector('#detail');
const state={lang:'en',page:'menu',avoid:[],spice:null,spiceMode:'exact',category:'all',country:'all',selected:null,dialogMode:'detail',filtersOpen:false};
let lastFocus=null;
let guide={step:'spice',spice:null,choice:null};
let ingredientQuestion=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>messages[state.lang][k]??messages.en[k]??k;
const icon=k=>icons[k]??'';
const recommendedIds=new Set(recommendedMenuIds);
const recommendedLabel=()=>t('recommended');
const recommendationBadge=d=>recommendedIds.has(d.id)?`<span class="recommendation-badge">${icon('star')}<span>${recommendedLabel()}</span></span>`:'';
const info=k=>storeInfo.find(x=>x.key===k)?.[state.lang]??'';
const spice=d=>d.spiceLevel===null?t('unknownSpice'):t(['notSpicy','mild','spicy'][d.spiceLevel]);
const visibleDishes=()=>filterDishes(dishes,state,{recs:state.country==='all'?null:recommendations.filter(r=>r.countryCode===state.country)});
const spiceBadge=d=>`<p class="spice spice-${d.spiceLevel}">${d.spiceLevel>0?`<span class="spice-peppers" aria-hidden="true">${icon('pepper').repeat(d.spiceLevel)}</span>`:''}<span>${esc(spice(d))}</span></p>`;
const languageButtons=()=>`<div class="language-buttons" role="group" aria-label="${t('chooseLanguage')}">${Object.entries(languages).map(([k,v])=>`<button data-lang="${k}" lang="${k}" aria-pressed="${state.lang===k}">${v}</button>`).join('')}</div>`;
function picture(d,large=false){return d.photo?`<button class="food-photo ${large?'large':''}" data-photo="${d.id}" aria-label="${esc(t('zoom')+' · '+d.names[state.lang])}"><img src="${d.photo}" alt="${esc(d.names[state.lang])}" width="1280" height="960" ${d.id==='M006'?'fetchpriority="high"':'loading="lazy"'}><span class="zoom-mark">${icon('zoom')}</span></button>`:`<div class="photo-missing">${icon('photo')}<span>${esc(t('photoPending'))}</span></div>`;}
function ingredients(d){return `<div class="ingredients-block"><p class="eyebrow">${esc(t('ingredients'))}</p><p class="ingredient-note">${esc(t('ingredientNote'))}</p>${d.contains.length?`<ul class="ingredient-icons">${d.contains.map(k=>`<li>${icon(k)}<span>${esc(t(k))}</span></li>`).join('')}</ul>`:`<p class="muted">${esc(t('unknown'))}</p>`}</div>`;}
function card(d){return `<article class="dish" id="dish-${d.id}"><div class="dish-heading"><span class="menu-number">${esc(t('guideNumber').replace('{number}',d.menuNumber))}</span><div><h3 class="dish-title">${recommendationBadge(d)}<span>${esc(d.names[state.lang])}</span></h3><p class="korean" lang="ko">${esc(d.nameKo)}</p></div></div><div class="dish-layout">${picture(d)}<div class="dish-information"><div class="price-row"><strong class="price">₩${d.priceKrw.toLocaleString('en-US')}</strong><span>${esc(d.units[state.lang])}</span></div><p class="description">${esc(d.descriptions[state.lang])}</p>${d.seasonal?`<p class="seasonal">${esc(t('seasonal'))} · ${esc(t('seasonNote'))}</p>`:''}${ingredients(d)}${!['dessert','drinks'].includes(d.categoryId)?spiceBadge(d):''}${d.wheatOption?`<p class="option-note">${esc(t('wheatOption'))}</p>`:''}<div class="dish-actions"><button class="detail-button" data-detail="${d.id}">${esc(t('details'))}</button><button class="staff-button" data-show-staff="${d.id}">${esc(t('showStaff'))}</button></div></div></div></article>`;}
function spiceArt(value){return value>0?`<span class="button-art pepper-art">${icon('pepper').repeat(value)}</span>`:`<span class="button-art neutral-art" aria-hidden="true">${value===0?'0':icon('filter')}</span>`;}
function spiceButtons(attribute,current,mode='exact'){
 return [[null,'anySpice'],[0,'notSpicy'],[1,mode==='max'?'upMild':'mild'],[2,mode==='max'?'spicyMax':'spicy']].map(([value,label])=>`<button class="illustrated-choice" ${attribute}="${value===null?'':value}" aria-pressed="${current===value}">${spiceArt(value)}<span>${esc(t(label))}</span></button>`).join('');
}
function spiceReference(id){return `<p class="spice-reference" ${id?`id="${id}"`:''}>${icon('pepper')}<span>${esc(t('spiceReference'))}</span></p>`;}
function giftEvent(){return `<section class="gift-event" aria-labelledby="gift-event-title"><svg class="gift-event-art" viewBox="0 0 40 40" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 19h26v16H7zM5 12h30v7H5zM20 12v23"/><path d="M20 12C8 12 9 2 14 4c4 1 6 8 6 8Zm0 0c12 0 11-10 6-8-4 1-6 8-6 8Z"/></svg><div><p class="gift-event-label">${esc(t('giftEventLabel'))}</p><h2 id="gift-event-title">${esc(t('giftEventTitle'))}</h2><p class="gift-event-note">${esc(t('giftEventNote'))}</p></div></section>`;}
function quickStart(){return `<section class="quick-start" aria-label="${esc(t('quickStart'))}"><h1 class="sr-only">${esc(t('menu'))}</h1><div class="quick-actions"><button class="guide-start" data-guide>${icon('star')}<span>${esc(t('guideStart'))}<small>${esc(t('guideTeaser'))}</small></span></button><button class="ingredient-help-button" data-ingredient-help>${icon('language')}<span>${esc(t('helpStart'))}</span></button></div><p class="quick-intro">${esc(t('guideIntro'))}</p><div class="quick-spice illustrated-options" role="group" aria-label="${esc(t('spice'))}" aria-describedby="quick-spice-reference">${spiceButtons('data-quick-spice',state.spice,state.spiceMode)}</div>${spiceReference('quick-spice-reference')}</section>`;}
function filters(){return `<details class="filter-panel" ${state.filtersOpen?'open':''}><summary>${icon('filter')}${esc(t('filters'))}</summary><div class="filter-body">
 <fieldset class="filter-section"><legend>${esc(t('spice'))}</legend><div id="spice" class="illustrated-options spice-options" role="group" aria-label="${esc(t('spice'))}" aria-describedby="filter-spice-reference">${spiceButtons('data-spice',state.spice,state.spiceMode)}</div>${spiceReference('filter-spice-reference')}</fieldset>
 <fieldset class="filter-section"><legend>${esc(t('recommendations'))}</legend><p class="filter-explanation">${esc(t('countryHelp'))}</p><div id="country" class="illustrated-options country-options" role="group" aria-label="${esc(t('recommendations'))}">${['all','JP','VN','MN'].map(k=>`<button class="illustrated-choice" data-country="${k}" aria-pressed="${state.country===k}"><span class="button-art">${flags[k]??icon('star')}</span><span>${esc(t(k))}</span></button>`).join('')}</div></fieldset>
 <button data-reset class="text-button">${esc(t('reset'))}</button>
 <fieldset class="filter-section ingredient-section"><legend>${esc(t('avoid'))}</legend><div class="ingredient-status-note" id="ingredient-filter-status">${icon('filter')}<div><strong>${esc(t('avoid'))}</strong><p>${esc(t('filterHelp'))}</p><button data-ingredient-contact>${esc(t('helpStart'))}</button></div></div><div class="filter-chips ingredient-options">${ingredientKeys.map(k=>`<button class="illustrated-choice" data-avoid="${k}" aria-describedby="ingredient-filter-status" aria-pressed="${state.avoid.includes(k)}"><span class="button-art">${icon(k)}</span><span>${esc(t(k))}</span></button>`).join('')}</div></fieldset>
 </div></details>`;}
function activeFilters(){
 const chosen=[];
 if(state.spice!==null)chosen.push(['spice',t(state.spiceMode==='max'?['notSpicy','upMild','spicyMax'][state.spice]:['notSpicy','mild','spicy'][state.spice])]);
 if(state.country!=='all')chosen.push(['country',t(state.country)]);
 for(const key of state.avoid)chosen.push(['avoid-'+key,t(key)]);
 return chosen.length?`<div class="active-filters" role="group" aria-label="${esc(t('activeFilters'))}"><p>${esc(t('activeFilters'))}</p><div>${chosen.map(([key,label])=>`<button data-clear-filter="${key}" aria-label="${esc(t('removeFilter').replace('{filter}',label))}">${esc(label)} <span aria-hidden="true">×</span></button>`).join('')}</div><p class="muted">${esc(t('activeFilterHelp'))}</p></div>`:'';
}
function clearFilter(key){
 const y=scrollY;
 if(key==='spice'){state.spice=null;state.spiceMode='exact';}
 else if(key==='country')state.country='all';
 else if(key.startsWith('avoid-'))state.avoid=state.avoid.filter(k=>k!==key.slice(6));
 render();
 (document.querySelector('[data-clear-filter]')??document.querySelector('[data-quick-spice=""]')).focus({preventScroll:true});
 scrollTo(0,y);
}
function menu(){const list=visibleDishes();return `<div class="menu-tools">${giftEvent()}${quickStart()}${filters()}${activeFilters()}<p class="filter-results" role="status" aria-live="polite">${esc(t(list.length===1?'resultsOne':'results').replace('{count}',list.length))}</p></div><div class="menu-sections">${categories.map((c,i)=>{const items=list.filter(d=>d.categoryId===c);return items.length?`<section class="menu-section" id="category-${c}" aria-labelledby="heading-${c}"><div class="section-heading"><span>${String(i+1).padStart(2,'0')}</span><h2 id="heading-${c}">${esc(t(c))}</h2><span class="section-count">${items.length}</span></div>${items.map(card).join('')}</section>`:'';}).join('')}${!list.length?`<div class="empty"><h2>${esc(t(state.avoid.length?'noVerifiedResults':'noResults'))}</h2><p>${esc(t(state.avoid.length?'noVerifiedResultsHelp':'noResultsHelp'))}</p>${state.avoid.length?`<button data-ingredient-help>${esc(t('helpStart'))}</button> `:''}<button data-reset>${esc(t('reset'))}</button></div>`:''}</div>`;}
function mapLinks(){return `<section class="map-card"><div class="map-card-heading">${icon('star')}<div><p class="eyebrow">GAYOUNGENE</p><h2>${esc(t('findUs'))}</h2></div></div><p lang="ko">${esc(storeLinks.addressKo)}</p><p class="muted">${esc(t('mapsHelp'))}</p><div class="map-actions"><a href="${esc(storeLinks.maps)}" target="_blank" rel="noopener noreferrer">${esc(t('openGoogleMaps'))}<span aria-hidden="true">↗</span></a><a href="${esc(storeLinks.directions)}" target="_blank" rel="noopener noreferrer">${esc(t('directions'))}<span aria-hidden="true">↗</span></a></div></section>`;}
function information(){const keys=state.page==='how'?['order','delivery','self','return','changes']:['intro','hours'];return `<div class="information-page"><p class="eyebrow">GAYOUNGENE</p><h1>${esc(t(state.page))}</h1>${state.page==='visit'?giftEvent()+mapLinks():''}${keys.map((k,i)=>`<section class="information-block"><span class="info-number">${String(i+1).padStart(2,'0')}</span><div><h2>${esc(t(k))}</h2><p>${esc(info(k))}</p></div></section>`).join('')}</div>`;}
function render(){document.documentElement.lang=state.lang;document.querySelector('.skip').textContent=t('skip');app.innerHTML=`<header class="site-header"><a href="#" class="brand" data-home aria-label="Gayoungene"><img src="./assets/gayoungene-logo.png" alt="가영이네 Gayoungene" width="1417" height="502"></a><div class="header-tools"><span class="language-label">${esc(t('chooseLanguage'))}</span>${languageButtons()}</div></header><nav class="primary-nav" aria-label="Gayoungene">${['menu','how','visit'].map(k=>`<button data-page="${k}" ${state.page===k?'aria-current="page"':''}>${esc(t(k))}</button>`).join('')}</nav><div class="site-layout ${state.page!=='menu'?'info-layout':''}">${state.page==='menu'?`<aside class="category-nav"><details id="category-menu" ${matchMedia('(min-width:900px)').matches?'open':''}><summary>${esc(t('categories'))}${icon('down')}</summary><div class="category-links">${categories.map((c,i)=>visibleDishes().some(d=>d.categoryId===c)?`<a href="#category-${c}" data-category="${c}"><span>${String(i+1).padStart(2,'0')}</span>${esc(t(c))}</a>`:'').join('')}</div></details></aside>`:''}<main id="main">${state.page==='menu'?menu():information()}</main></div><footer><img src="./assets/gayoungene-logo.png" alt="Gayoungene" width="1417" height="502"><p>${esc(t('translationNote'))}</p><a class="footer-map-link" href="${esc(storeLinks.maps)}" target="_blank" rel="noopener noreferrer">${esc(t('openGoogleMaps'))} ↗</a><br><a href="./icon-credits.txt">Icon credits</a></footer>`;document.querySelector('.filter-panel')?.addEventListener('toggle',e=>{if(e.target.isConnected)state.filtersOpen=e.target.open;});}
function renderDialog(){if(['guide','guide-staff','ingredient-help'].includes(state.dialogMode)){renderAuxDialog();return;}const d=dishes.find(x=>x.id===state.selected);if(!d)return;const zoom=state.dialogMode==='photo',staff=state.dialogMode==='staff';dialog.className=zoom?'photo-dialog':'';dialog.innerHTML=`<div class="dialog-top">${languageButtons()}<button data-close class="close-button" aria-label="${esc(t('close'))}">${icon('close')}</button></div><div class="dialog-body"><p class="eyebrow">${esc(t('guideNumber').replace('{number}',d.menuNumber))}</p><h2 id="detail-title" class="dish-title">${recommendationBadge(d)}<span>${esc(staff?d.nameKo:d.names[state.lang])}</span></h2><p class="korean" lang="${staff?state.lang:'ko'}">${esc(staff?d.names[state.lang]:d.nameKo)}</p>${zoom?`<img class="expanded-photo" src="${d.photo}" alt="${esc(d.names[state.lang])}">`:staff?`<p>${esc(t('staffNote'))}</p>`:`${ingredients(d)}<h3>${esc(t('moreIngredients'))}</h3><p>${esc(t('pending'))}</p>${d.otherMeat?`<p>${esc(t('otherMeat'))}</p>`:''}${d.wheatOption?`<p>${esc(t('wheatOption'))}</p>`:''}<dl class="ingredient-status">${ingredientKeys.map(k=>`<div><dt>${esc(t(k))}</dt><dd>${esc(t(d.ingredients[k]))}</dd></div>`).join('')}</dl><p>${esc(info('changes'))}</p><button class="primary-button" data-staff>${esc(t('showStaff'))}</button>`}</div>`;}
function openDish(id,mode){if(!dishes.some(d=>d.id===id))return;lastFocus=document.activeElement;state.selected=id;state.dialogMode=mode;renderDialog();dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('[data-close]').focus();const u=new URL(location.href);u.searchParams.set('menu',id);history.replaceState(null,'',u);}
function closeDialog(){const mode=state.dialogMode;const id=state.selected;dialog.close();document.body.style.overflow='';state.selected=null;const u=new URL(location.href);u.searchParams.delete('menu');history.replaceState(null,'',u);const trigger=lastFocus?.isConnected?lastFocus:document.querySelector(['guide','guide-staff'].includes(mode)?'[data-guide]':mode==='ingredient-help'?(lastFocus?.hasAttribute('data-ingredient-contact')?'[data-ingredient-contact]':'[data-ingredient-help]'):lastFocus?.dataset.photo?'[data-photo="'+id+'"]':lastFocus?.dataset.showStaff?'[data-show-staff="'+id+'"]':'[data-detail="'+id+'"]');trigger?.focus({preventScroll:true});}
function changeLanguage(lang){if(!languages[lang])return;const y=scrollY;state.lang=lang;render();if(dialog.open){renderDialog();dialog.querySelector('[data-lang="'+lang+'"]')?.focus();}window.scrollTo(0,y);}
function reset(){state.filtersOpen=true;state.avoid=[];state.spice=null;state.spiceMode='exact';state.country='all';state.category='all';render();}
app.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-home')){e.preventDefault();state.page='menu';render();window.scrollTo(0,0);}else if(el.dataset.lang)changeLanguage(el.dataset.lang);else if(el.dataset.page){state.page=el.dataset.page;render();window.scrollTo(0,0);}else if(el.dataset.category){e.preventDefault();const d=document.querySelector('#category-menu');if(d&&!matchMedia('(min-width:900px)').matches)d.open=false;document.querySelector('#category-'+el.dataset.category)?.scrollIntoView({behavior:'smooth',block:'start'});}else if(el.dataset.clearFilter)clearFilter(el.dataset.clearFilter);else if(el.hasAttribute('data-guide'))openAux('guide');else if(el.hasAttribute('data-ingredient-help')||el.hasAttribute('data-ingredient-contact'))openAux('ingredient-help');else if(el.hasAttribute('data-spice')||el.hasAttribute('data-country')){const kind=el.hasAttribute('data-spice')?'spice':'country';const value=el.dataset[kind],y=scrollY;state.filtersOpen=true;if(kind==='spice'){state.spice=value===''?null:Number(value);state.spiceMode='exact';}else state.country=value;render();document.querySelector('[data-'+kind+'="'+value+'"]').focus({preventScroll:true});scrollTo(0,y);}else if(el.hasAttribute('data-quick-spice')){state.spice=el.dataset.quickSpice===''?null:Number(el.dataset.quickSpice);state.spiceMode='exact';const value=el.dataset.quickSpice,y=scrollY;render();document.querySelector('[data-quick-spice="'+value+'"]').focus({preventScroll:true});scrollTo(0,y);}else if(el.dataset.showStaff)openDish(el.dataset.showStaff,'staff');else if(el.dataset.photo)openDish(el.dataset.photo,'photo');else if(el.dataset.detail)openDish(el.dataset.detail,'detail');else if(el.dataset.avoid){const k=el.dataset.avoid;if(!ingredientKeys.includes(k))return;state.avoid=state.avoid.includes(k)?state.avoid.filter(v=>v!==k):[...state.avoid,k];state.filtersOpen=true;const y=scrollY;render();document.querySelector('[data-avoid="'+k+'"]').focus({preventScroll:true});scrollTo(0,y);}else if(el.hasAttribute('data-reset'))reset();});
dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(handleAuxClick(b))return;if(b.dataset.lang)changeLanguage(b.dataset.lang);if(b.hasAttribute('data-close'))closeDialog();if(b.hasAttribute('data-staff')){state.dialogMode='staff';renderDialog();dialog.scrollTop=0;dialog.querySelector('[data-close]').focus();}});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
const money=value=>'₩'+value.toLocaleString('en-US');
function guideChoices(){return getGuideChoices(dishes,recommendedMenuIds,guide.spice);}
function guideItem(d,staff=false){return `<div class="guide-item">${!staff&&d.photo?`<img src="${d.photo}" alt="${esc(d.names[state.lang])}" width="1280" height="960">`:''}<div><p class="eyebrow">${esc(t('guideNumber').replace('{number}',d.menuNumber))}</p><h3 ${staff?'lang="ko"':''}>${esc(staff?d.nameKo:d.names[state.lang])}</h3><p class="korean" lang="${staff?state.lang:'ko'}">${esc(staff?d.names[state.lang]:d.nameKo)}</p><p class="guide-item-price">${money(d.priceKrw)} <span>${esc(d.units[state.lang])}</span></p>${!staff?`<p class="guide-description">${esc(d.descriptions[state.lang])}</p>${spiceBadge(d)}${!d.photo?`<p class="muted">${esc(t('photoPending'))}</p>`:''}`:''}</div></div>`;}
function renderAuxDialog(){
 dialog.className='guide-dialog';
 let title='',body='';
 if(state.dialogMode==='ingredient-help'){
  title=t('helpTitle');
  const ko=ingredientQuestion==='meat'?'고기나 생선이 들어가지 않은 메뉴가 있나요? 육수·소스·가공식품의 원재료도 확인해 주세요.':'음식 알레르기가 있습니다. 전체 원재료와 조리 중 교차 접촉 가능성을 확인하고 싶습니다. 어떤 식품에 알레르기가 있는지는 직접 말씀드리겠습니다.';
  body=`<p>${esc(t('helpIntro'))}</p><div class="guide-options">${[['meat','helpMeat'],['allergy','helpAllergy']].map(([v,k])=>`<button data-ingredient-question="${v}" aria-pressed="${ingredientQuestion===v}">${esc(t(k))}</button>`).join('')}</div>${ingredientQuestion?`<section class="staff-question" aria-live="polite"><h3>${esc(t('showStaff'))}</h3><p lang="ko">${ko}</p><p>${esc(t(ingredientQuestion==='meat'?'helpMeatText':'helpAllergyText'))}</p><p class="muted">${esc(t('helpNote'))}</p></section>`:''}`;
 }else if(state.dialogMode==='guide-staff'){
  const choice=guideChoices()[guide.choice];
  title=t('showStaff');body=`${guideItem(choice,true)}<p>${esc(t('staffNote'))}</p><button data-guide-back="results">${esc(t('guideBack'))}</button>`;
 }else if(guide.step==='spice'){
  title=t('guideSpice');body=`<div class="guide-options illustrated-options" role="group" aria-label="${esc(t('spice'))}">${spiceButtons('data-guide-spice',guide.spice)}</div>${spiceReference()}`;
 }else{
  title=t('guideResults');const choices=guideChoices();body=`<p class="guide-selection">${esc(t(guide.spice===null?'anySpice':['notSpicy','mild','spicy'][guide.spice]))}</p><p class="muted">${esc(t('guideReason'))}</p><p class="ingredient-note">${esc(t('ingredientNote'))}</p>${choices.length?choices.map((d,i)=>`<article class="guide-choice">${guideItem(d)}<button class="staff-button" data-guide-choice="${i}">${esc(t('showStaff'))}</button></article>`).join(''):`<p class="guide-empty">${esc(t('guideNone'))}</p>`}<div class="guide-options"><button data-guide-back="spice">${esc(t('guideBack'))}</button><button data-guide-browse>${esc(t('guideBrowse'))}</button></div>`;
 }

 dialog.innerHTML=`<div class="dialog-top">${languageButtons()}<button data-close class="close-button" aria-label="${esc(t('close'))}">${icon('close')}</button></div><div class="dialog-body"><h2 id="detail-title" tabindex="-1">${esc(title)}</h2>${body}</div>`;
}
function refreshAux(){renderDialog();dialog.scrollTop=0;dialog.querySelector('#detail-title').focus({preventScroll:true});}
function openAux(mode){lastFocus=document.activeElement;state.selected=null;state.dialogMode=mode;guide={step:'spice',spice:null,choice:null};ingredientQuestion=null;renderDialog();dialog.showModal();document.body.style.overflow='hidden';dialog.querySelector('#detail-title').focus();}
function handleAuxClick(button){
 if(button.hasAttribute('data-guide-spice')){guide.spice=button.dataset.guideSpice===''?null:Number(button.dataset.guideSpice);guide.step='results';refreshAux();return true;}
 if(button.dataset.guideBack){state.dialogMode='guide';guide.step=button.dataset.guideBack;refreshAux();return true;}
 if(button.hasAttribute('data-guide-choice')){guide.choice=Number(button.dataset.guideChoice);if(!guideChoices()[guide.choice])return true;state.dialogMode='guide-staff';refreshAux();return true;}
 if(button.hasAttribute('data-guide-browse')){closeDialog();return true;}
 if(button.dataset.ingredientQuestion){ingredientQuestion=button.dataset.ingredientQuestion;refreshAux();return true;}
 return false;
}
render();const initial=new URL(location.href).searchParams.get('menu');if(initial){const d=dishes.find(d=>d.id===initial||d.menuNumber===initial);if(d)openDish(d.id,'detail');}
// Optional browser integration shares the exact same verified-ingredient filter.
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'configure_menu_filters',description:'Filter menu items. Unconfirmed ingredient absences are excluded. Does not place orders.',inputSchema:{type:'object',properties:{avoid:{type:'array',items:{type:'string',enum:ingredientKeys}},maxSpice:{type:['integer','null'],minimum:0,maximum:2}},required:['avoid','maxSpice'],additionalProperties:false},execute(input){if(!input||!Array.isArray(input.avoid)||input.avoid.some(k=>!ingredientKeys.includes(k))||![null,0,1,2].includes(input.maxSpice))throw Error('Invalid filters');state.avoid=[...new Set(input.avoid)];state.spice=input.maxSpice;state.spiceMode='max';state.page='menu';state.filtersOpen=true;render();return {items:visibleDishes().map(d=>({id:d.id,name:d.names[state.lang]}))};}});}catch{}}
